	"config.extRecommended.piDeckTodo": "PiDeck 內建：當前有效計劃 TODO 擴充套件，支援顯式替換、恢復和分支級持久化，並在對話中追蹤任務進度。",
	"config.extRecommended.piDeckPlanMode": "PiDeck 內建：計劃模式擴充套件，讓 AI 在回覆前首先生成執行計劃，複雜任務一目瞭然。",
	"config.extRecommended.piDeckGoalMode": "PiDeck 內建：目標模式擴充套件，圍繞一條目標自動連續推進，直到完成、阻塞或你暫停。",
	"config.extRecommended.piDeckAskQuestion": "PiDeck 內建：在對話中插入精心設計的問題卡片，引導 AI 給出更精準的回答。",
	"config.extRecommended.piDeckNulRedirectFix": "PiDeck 內建：修復 Windows 下 Pi 重定向到 NUL 裝置時可能產生的殘留檔案問題。",
	"config.extRecommended.contextMode": "MCP 外掛，可節省 98% 的上下文視窗。沙箱程式碼執行、FTS5 知識庫和意圖驅動搜尋。",
	"config.extRecommended.piWebAccess": "網路搜尋、URL 抓取、GitHub 倉庫克隆、PDF 提取、YouTube 影片理解和本地影片分析。",
	"config.extRecommended.piMcpAdapter": "MCP（Model Context Protocol）介面卡擴充套件，讓 Pi 可以連線任何 MCP 伺服器。",
	"config.extRecommended.piSubagents": "任務委派擴充套件，支援鏈式、並行執行和 TUI 澄清。可將複雜任務拆解給多個子 Agent。",
	// 已安装列表：内置扩展一行简介（ExtensionTableRow 按 source 映射 builtInExtDesc.*）
	"config.builtInExtDesc.pi-deck-request-size-recovery": "請求體超限自動恢復：識別閘道器 413/請求體過大錯誤，徵得同意後臨時切換大上限模型壓縮會話再切回，解除無法傳送的死鎖。",
	"config.builtInExtDesc.pi-deck-ask-question": "註冊 ask_question 工具：模型可通過統一的提問卡片向你提問（單選/多選/確認/輸入，多問題時以 Tab 展開），選擇題恆帶自定義輸入，回答回傳給模型。",
	"config.builtInExtDesc.pi-deck-goal-mode": "目標模式：圍繞一條目標自動續輪推進，直到完成、阻塞、暫停或到達輪次上限；狀態跨重啟可恢復。",
	"config.builtInExtDesc.pi-deck-model-trace": "模型請求快照：把 Pi 實際發給供應商的請求體（系統提示詞/上下文訊息/工具表）記入 RPC 日誌的「模型」檢視，排查「模型到底收到了什麼」；快照只存本機，超限自動截斷。",
	"config.builtInExtDesc.pi-deck-nul-redirect-fix": "NUL 重定向修復：bash 執行前把「> nul」等 Windows 重定向改寫為 /dev/null，避免 Git Bash 產生刪不掉的 nul 檔案。",
	"config.builtInExtDesc.pi-deck-plan-mode": "計劃模式：先以只讀工具集產出編號計劃，經你選擇執行/停留/修改後再恢復寫工具，[DONE:n] 標記驅動進度展示。",
	"config.builtInExtDesc.pi-deck-retry-no-body": "瞬態錯誤重試增強：識別閘道器空響應、中文「服務暫時不可用」、stream_read_error 等 Pi 重試名單外的瞬態故障並改寫，觸發自動重試。",
	"config.builtInExtDesc.pi-deck-security-gate": "安全門：按會話安全等級策略攔截工具呼叫——危險 bash 命令彈窗確認或直接拒絕；策略快照熱更新，無需重啟。",
	"config.builtInExtDesc.pi-deck-gui-bridge": "GUI 擴充套件橋（預設關閉，需要時在此開啟）：把 Pi 在 RPC 模式下被丟棄的宣告式 UI 擴充套件點（頂部區/底部狀態區/狀態列/輸入框掛件/流式狀態行/摺疊思考塊標籤/會話標題/輸入框本體）接回桌面端，並另供一套寫法同形的 GUI 專屬擴充套件點與 GUI 作畫工廠。重啟會話後生效。",
	"config.builtInExtDesc.pi-deck-ext-points": "擴充套件點面板（預設關閉，需要時在此開啟；建議同時開啟 GUI 擴充套件橋）：在設定裡列出 Pi + PiDeck 的全部可掛載點，標好每條在桌面端會不會生效；勾選並寫下用途後可生成一份交給 agent 的開發草稿。清單在執行時從 Pi 的型別定義讀取，沒有構建期快照要同步。重啟會話後生效。",
	"bridge.control.cancellable": "可取消",
	"bridge.node.copy": "複製",
	"bridge.node.copied": "已複製",
	"config.builtInExtDesc.pi-deck-session-title": "會話標題生成：首輪結束後用獨立最小上下文非同步生成簡短標題，不修改主對話與會話記錄。",
	"config.builtInExtDesc.pi-deck-subagents": "子代理狀態橋接：訂閱 pi-subagents / acp_delegate 委託鏈的生命週期事件，把各子代理的執行狀態與結果快照推給桌面端子代理面板展示（本身不派發子代理）。",
	"config.builtInExtDesc.pi-deck-todo": "待辦計劃管理：分支級持久化的當前工作計劃，僅通過 list/add/update/delete/replace/restore/clear 顯式工具變更，切換分支自動恢復對應計劃。",
	"config.builtInExtDesc.pi-deck-trash-guard": "回收站守衛：攔截 rm/Remove-Item 等刪除類命令，執行前把每個目標複製送入系統回收站留底，原命令照常執行。",
	"config.builtInExtDesc.pi-deck-vision": "視覺橋接：給 DeepSeek 等無視覺模型「裝上眼睛」，把貼上/上傳及工具結果中的圖片轉成文字描述後再交給模型。",
