	"settings.remote.guide.title": "外網訪問操作指南",
	"settings.remote.guide.subtitle": "選擇一種渠道，按步驟完成安裝與連線",
	"settings.remote.guide.cf.intro": "Cloudflare Tunnel 免註冊模式：本機執行 cloudflared，Cloudflare 分配一個臨時 https 地址轉發到 PiDeck 的 Web 服務。手機零安裝、任何網路可訪問。",
	"settings.remote.guide.cf.step1": "第 1 步 · 安裝 cloudflared（命令列任選其一，或到 GitHub Releases 手動下載）",
	"settings.remote.guide.cf.step1Mac": "macOS 用 Homebrew：",
	"settings.remote.guide.cf.releaseLink": "GitHub Releases 手動下載",
	"settings.remote.guide.cf.step2": "第 2 步 · 安裝完成後回到本頁，點「重新檢測」，狀態應變為「已就緒」",
	"settings.remote.guide.cf.step3": "第 3 步 · 確保 Web 服務已開啟且 Token 鑑權已開啟，點「啟動外網訪問」",
	"settings.remote.guide.cf.step4": "第 4 步 · 複製生成的 https 地址（或掃碼），在手機任意瀏覽器開啟即可",
	"settings.remote.guide.cf.notice":
		"注意：免註冊隧道無需帳號，但地址每次重啟都會變化；流量經 Cloudflare 中轉，請務必保持 Token 鑑權開啟，不要把連結分享給不信任的人。國內直連 Cloudflare 邊緣節點可能較慢（運營商對境外線路限速），隧道已強制 TCP 連線以規避 UDP 限速；若仍慢，開啟代理客戶端的 TUN/系統級模式通常可改善（HTTP 代理無法加速隧道本體）。",
	"settings.remote.guide.ts.intro": "Tailscale 把你的電腦和手機組成一個端到端加密的虛擬區域網：不暴露公網、地址固定、P2P 直連速度快。個人免費額度（100 臺裝置）對個人使用者綽綽有餘。",
	"settings.remote.guide.ts.step1": "第 1 步 · 在電腦和手機上都安裝 Tailscale 客戶端（官網下載，手機商店搜 Tailscale）",
	"settings.remote.guide.ts.downloadLink": "官網下載頁",
	"settings.remote.guide.ts.step2": "第 2 步 · 兩臺裝置登入同一帳號（Google/GitHub/微軟均可），電腦端保持已連線",
	"settings.remote.guide.ts.step3": "第 3 步 · 回到本頁點「重新檢測」，出現虛擬 IP（100.x.x.x）後即可複製直連地址，在手機瀏覽器開啟",
	"settings.remote.guide.ts.step4": "第 4 步 ·（可選）要固定 HTTPS 地址或把 Web 端安裝到手機主屏（PWA），點「啟用 HTTPS 入口」；如失敗請在管理臺開啟 MagicDNS 與 HTTPS 證書",
	"settings.remote.guide.ts.adminLink": "開啟 Tailscale 管理臺（DNS 設定）",
	"settings.remote.guide.ts.notice": "怎麼選：只給自己用、在意隱私與速度 → Tailscale；要發連結給別人臨時看、或手機不想裝任何東西 → Cloudflare 隧道。",
